#include <windows.h>
#include <GL/gl.h>
#include <stdio.h>
int main(void){PIXELFORMATDESCRIPTOR p={0};HWND w=CreateWindowA("STATIC","WineMetalGL share",WS_OVERLAPPEDWINDOW,0,0,64,64,0,0,0,0);HDC d=GetDC(w);p.nSize=sizeof(p);p.nVersion=1;p.dwFlags=PFD_DRAW_TO_WINDOW|PFD_SUPPORT_OPENGL;p.iPixelType=PFD_TYPE_RGBA;p.cColorBits=32;int f=ChoosePixelFormat(d,&p);if(!f||!SetPixelFormat(d,f,&p))return 12;HGLRC a=wglCreateContext(d),b=wglCreateContext(d);if(!a||!b)return 13;if(!wglShareLists(a,b))return 14;GLuint texture=0;unsigned char pixel[4]={255,0,0,255};wglMakeCurrent(d,a);glGenTextures(1,&texture);glBindTexture(GL_TEXTURE_2D,texture);glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA,1,1,0,GL_RGBA,GL_UNSIGNED_BYTE,pixel);wglMakeCurrent(d,b);if(!glIsTexture(texture))return 15;printf("WINEMETALGL_WGL_SHARE_LISTS_OK\n");printf("WINEMETALGL_WGL_SHARED_OBJECTS_OK\n");wglDeleteContext(a);wglDeleteContext(b);ReleaseDC(w,d);DestroyWindow(w);return 0;}
